use crate::stage13::{SecureBootEnable,SecureBootOtp,SECURE_BOOT_OTP_OFFSET,ensure_secure_boot_enabled};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum SecureBootPolicy{Enabled,EnabledNow,VerificationFailed{first:u8,second:u8}}
pub fn ensure_and_verify_secure_boot<I:SecureBootOtp>(io:&mut I)->Result<SecureBootPolicy,I::Error>{let changed=matches!(ensure_secure_boot_enabled(io)?,SecureBootEnable::EnabledNow);let a=io.read_secure_byte(SECURE_BOOT_OTP_OFFSET)?;let b=io.read_secure_byte(SECURE_BOOT_OTP_OFFSET)?;if a.count_ones()>3||b.count_ones()>3{Ok(if changed{SecureBootPolicy::EnabledNow}else{SecureBootPolicy::Enabled})}else{Ok(SecureBootPolicy::VerificationFailed{first:a,second:b})}}
#[cfg(test)]mod tests{use super::*;struct O{v:u8,w:u8}impl SecureBootOtp for O{type Error=();fn read_secure_byte(&mut self,_:u16)->Result<u8,()>{Ok(self.v)}fn write_secure_byte(&mut self,_:u16,v:u8)->Result<(),()>{self.v=v;self.w+=1;Ok(())}}#[test]fn policy(){let mut o=O{v:0,w:0};assert_eq!(ensure_and_verify_secure_boot(&mut o),Ok(SecureBootPolicy::EnabledNow));assert_eq!((o.v,o.w),(0xff,1));let mut bad=O{v:3,w:0};assert!(matches!(ensure_and_verify_secure_boot(&mut bad),Ok(SecureBootPolicy::VerificationFailed{..})));}}
